function merge(existing){
 var out=Array.isArray(existing)?existing.slice():[],ids=Object.create(null);out.forEach(function(g){if(g&&g.id)ids[g.id]=1});
 out.forEach(function(g){if(!g||!g.id)return;var m=existingMap[g.id];if(m){g.subjectKey=m[0];g.chapterKeys=(m[1]||[]).slice();g.chapterKey=g.chapterKeys[0]||''}else if(!g.subjectKey){var z=(g.id+' '+g.t+' '+g.d).toLowerCase();if(/chem|ion|flame|organic|stoich|periodic|electron|molecul|reaction|enthalpy|electrochem|solution|environment/.test(z)){g.subjectKey='chemistry';g.chapterKeys=['chem1-04']}else if(/math|matrix|slope|circle|vector|calculus|probab|conic|binomial|trig|polynomial/.test(z)){g.subjectKey='math';g.chapterKeys=['math1-01']}else if(/physics|projectile|cannon|force|motion|wave|unit|pendulum|magnetic|quantum/.test(z)){g.subjectKey='physics';g.chapterKeys=['phy1-03']}else{g.subjectKey='mixed';g.chapterKeys=[]}}});
 games.forEach(function(g){if(!ids[g.id]){out.push(g);ids[g.id]=1}});
 return out;
}
